-- aria:supervisor-unloading's "Goods Receipt — Count by Item" section already
-- has received_qty / invoice_qty (visible for every flow_variant except
-- M10.TankerInbound, so live for M10.ReturnStockIn today) but no computed
-- difference and no reason field, and neither was ever projected anywhere —
-- silently dropped. Per direct request ("Dispatch front officer: invoice
-- stock and received stock difference with reason, manual entry"), adding
-- qty_difference_display (computed, read-only) and qty_diff_reason
-- (manual textarea) right next to them, then persisting all 3 (plus the two
-- pre-existing fields themselves) into tanker_unloading_detail for
-- M10.ReturnStockIn.
UPDATE page_version pv
  JOIN page_definition pd ON pd.current_version_id = pv.id
   SET pv.body_json = '{"kind": "layout","schemaVersion": 2,"slug": "aria:supervisor-unloading","title": "Unloading Supervisor — Goods Receipt","status": "published","version": 1,"roles": ["UnloadingSupervisor","StoreKeeper","Manager","TenantAdmin"],"dataSources": [],"streams": [],"layout": [{"kind": "Grid","columns": 12,"gap": 16,"children": [{"kind": "Section","title": "Vehicle & Reference","span": 12,"subtitle": "Auto-fills from the gate pass assigned to your queue. Confirm before counting goods.","children": [{"kind": "Form","submitLabel": "","bindings": {"fields": [{"name": "gp_number","label": "Gate Pass # (scan / pick / type)","type": "select","required": true,"scannable": true,"freeSolo": true,"optionsSource": {"type": "datasource","spec": {"type": "entity","entity": "GatePass","joins": [{"entity": "WorkflowInstance","as": "wi","on": "gate_pass.workflow_instance_id = wi.id"}],"filter": {"and": [{"field": "wi.assigned_role","op": "eq","value": "UnloadingSupervisor"},{"field": "wi.status","op": "eq","value": "OPEN"}]},"select": ["id","gp_number"],"sort": [{"field": "gp_number","dir": "desc"}]},"valueField": "gp_number","labelField": "gp_number"},"onChangeFill": {"vehicle_no": "vehicle_no","reference_no": "reference_no","instanceId": "workflow_instance_id","flow_variant_code": "flow_variant_code"}},{"name": "vehicle_no","label": "Vehicle","type": "text","readOnly": true},{"name": "flow_variant_code","label": "Flow Variant","type": "text","readOnly": true},{"name": "flow_kind","label": "Receipt Type","type": "select","options": [{"label": "Raw Material — bottled / canned / drum (inbound from vendor)","value": "RM_INBOUND"},{"label": "Packing Material — cartons / bottles / caps / labels (inbound)","value": "PACKING_INBOUND"},{"label": "Return Stock — FG returned by customer","value": "RETURN_INBOUND"},{"label": "Inter-Unit Transfer In","value": "INTER_UNIT_IN"}],"visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'","requiredWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "reference_no","label": "Reference (PO# / GRN# / RN#)","type": "text","visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'","requiredWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"}]}}]},{"kind": "Section","title": "Goods Receipt — Count by Item","span": 12,"subtitle": "Verify item code, count cases physically as you unload. Repeat the block for each item in the truck.","children": [{"kind": "Form","submitLabel": "","bindings": {"fields": [{"name": "item_code","label": "Item / SKU Code","type": "text","placeholder": "GIN-1L-IDH","helperText": "Scan barcode or pick from SKU master","visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'","requiredWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "item_description","label": "Item Name (auto-fill)","type": "text","readOnly": true,"visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "uom","label": "UOM","type": "select","options": [{"label": "Cases","value": "CASE"},{"label": "Bottles","value": "BOTTLE"},{"label": "Bundles","value": "BUNDLE"},{"label": "Pallets","value": "PALLET"},{"label": "Bags","value": "BAG"},{"label": "Pieces","value": "NOS"},{"label": "Drums","value": "DRUM"},{"label": "Kilograms","value": "KG"},{"label": "Litres","value": "L"}],"visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'","requiredWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "received_qty","label": "Quantity Received","type": "number","helperText": "Counted physically as cases / bottles came off the truck","visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'","requiredWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "invoice_qty","label": "Invoice Qty (from PO / vendor invoice)","type": "number","helperText": "System flags variance if Received ≠ Invoice","visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "qty_difference_display","label": "Difference (Received − Invoice)","type": "number","readOnly": true,"visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'","computedFrom": "#form.received_qty - #form.invoice_qty"},{"name": "qty_diff_reason","label": "Difference Reason (if any)","type": "textarea","rows": 2,"visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "batch_no","label": "Batch / Lot Number","type": "text","placeholder": "B26-0421-A","visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "mfg_date","label": "Manufacturing Date","type": "date","visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "expiry_date","label": "Expiry / Best-Before Date","type": "date","visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"}]}}]},{"kind": "Section","title": "Bin / Godown Allocation","span": 12,"subtitle": "Pick the destination bin/godown. Stock balance updates immediately on confirmation.","children": [{"kind": "Form","submitLabel": "","bindings": {"fields": [{"name": "godown_code","label": "Godown","type": "select","options": [{"label": "G1 — Main Stores (free 62%)","value": "G1"},{"label": "G2 — Packing Material Stores (free 41%)","value": "G2"},{"label": "G3 — Returns / Quarantine (free 88%)","value": "G3"},{"label": "G4 — FG Stores (free 35%)","value": "G4"}],"visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'","requiredWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "bin_code","label": "Bin / Rack","type": "select","options": [{"label": "A-01 (free)","value": "A-01"},{"label": "A-02 (partial — 30%)","value": "A-02"},{"label": "A-03 (free)","value": "A-03"},{"label": "B-01 (full — assign next)","value": "B-01"},{"label": "B-02 (free)","value": "B-02"},{"label": "C-01 (free)","value": "C-01"},{"label": "C-02 (free)","value": "C-02"}],"visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'","requiredWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "stack_pattern","label": "Stacking Pattern","type": "select","options": [{"label": "Standard pallet (4 cases / layer × 5 layers)","value": "STD_PALLET"},{"label": "Bin stack (max 8 layers)","value": "BIN_STACK"},{"label": "Single layer (fragile)","value": "SINGLE"}],"visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "storage_condition","label": "Storage Condition","type": "select","options": [{"label": "Ambient","value": "AMBIENT"},{"label": "Cool & Dry","value": "COOL_DRY"},{"label": "Quarantine — QC pending","value": "QUARANTINE"}],"visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"}]}}]},{"kind": "Section","title": "Damage / Short-Receipt Check","span": 12,"subtitle": "Capture damaged or short items separately. They route to QC for vendor debit-note.","children": [{"kind": "Form","submitLabel": "","bindings": {"fields": [{"name": "damaged_qty","label": "Damaged Quantity","type": "number","helperText": "Cases / bottles found damaged on unload. Photo evidence required.","visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "damage_reason","label": "Damage Reason","type": "select","options": [{"label": "Transport damage (crushed / dented)","value": "TRANSPORT"},{"label": "Packing leak","value": "LEAK"},{"label": "Seal broken","value": "SEAL_BROKEN"},{"label": "Expired before receipt","value": "EXPIRED"},{"label": "Other (see notes)","value": "OTHER"}],"visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "short_qty","label": "Short Quantity (vs invoice)","type": "number","helperText": "Triggers debit-note workflow against vendor","visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "damage_photo","label": "Damage / Short-Receipt Photo","type": "file","accept": "image/*","visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"},{"name": "notes","label": "Notes","type": "textarea","rows": 3,"visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"}]}}]},{"kind": "Section","title": "Confirm Storage Complete","span": 12,"children": [{"kind": "Form","bindings": {"fields": [{"name": "supervisor_id","label": "Supervisor (auto-fill)","type": "text","readOnly": true},{"name": "start_ts","label": "Unloading Start","type": "datetime-local"},{"name": "finish_ts","label": "Unloading Finish","type": "datetime-local"},{"name": "unload_seal_unlock_no","label": "Seal # broken on unload","type": "text"},{"name": "grn_to_create","label": "Create GRN now?","type": "select","options": [{"label": "✓ Yes — auto-create GRN against PO","value": "YES"},{"label": "Later — supervisor will create from GRN page","value": "NO"}],"visibleWhen": "#form.flow_variant_code != \'M10.TankerInbound\'","requiredWhen": "#form.flow_variant_code != \'M10.TankerInbound\'"}]}},{"kind": "WorkflowActionButton","action": "workflow.transition","label": "Close Unloading — Stock Updated","variant": "primary"}]}]}]}'
 WHERE pd.code = 'aria:supervisor-unloading' AND pv.status = 'PUBLISHED';

ALTER TABLE tanker_unloading_detail
  ADD COLUMN IF NOT EXISTS received_qty DECIMAL(12,3) DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS invoice_qty DECIMAL(12,3) DEFAULT NULL,
  ADD COLUMN IF NOT EXISTS qty_diff_reason VARCHAR(255) DEFAULT NULL;

INSERT INTO entity_field_registry (id, tenant_id, entity_code, field_code, display_label, data_type, filterable, sortable, searchable, required, widget_kind)
SELECT (SELECT COALESCE(MAX(id),0) FROM entity_field_registry x)+ROW_NUMBER() OVER (ORDER BY c.fc),
       -1,'TankerUnloadingDetail',c.fc,c.lbl,c.dt,c.filt,c.sort,c.srch,0,c.wk
FROM (SELECT 'received_qty' fc,'Received Qty' lbl,'DECIMAL' dt,0 filt,1 sort,0 srch,'number' wk
      UNION ALL SELECT 'invoice_qty','Invoice Qty','DECIMAL',0,1,0,'number'
      UNION ALL SELECT 'qty_diff_reason','Qty Difference Reason','STRING',0,0,1,'textarea') c
WHERE NOT EXISTS (SELECT 1 FROM entity_field_registry WHERE entity_code='TankerUnloadingDetail' AND field_code=c.fc);

UPDATE m0_workflow_projection
   SET field_map_json = JSON_SET(field_map_json,
         '$.received_qty', JSON_ARRAY('received_qty'),
         '$.invoice_qty', JSON_ARRAY('invoice_qty'),
         '$.qty_diff_reason', JSON_ARRAY('qty_diff_reason'))
 WHERE tenant_id = -1 AND workflow_code = 'M10.ReturnStockIn' AND target_table = 'tanker_unloading_detail';
